mapper.select:
SELECT seq_id, boardType, title, nickname, regdate, viewCount, commentCount, likeCount FROM ( SELECT combined_boards.*, ROW_NUMBER() OVER (ORDER BY regdate DESC) AS RNUM FROM ( (SELECT notice.notice_post_id AS seq_id, 'tblNotice' AS boardType, notice.notice_header AS title, a.admin_name AS nickname, notice.notice_regdate AS regdate, notice.notice_view_count AS viewCount, 0 AS commentCount, 0 AS likeCount FROM tblNoticePost notice LEFT JOIN tblAdmin a ON notice.admin_id = a.admin_id) UNION ALL (SELECT qb.question_board_id AS seq_id, 'tblQuestionBoard' AS boardType, qb.question_board_title AS title, u.nickname AS nickname, qb.question_board_regdate AS regdate, qb.question_board_view_count AS viewCount, qb.question_board_comment_count AS commentCount, qb.question_board_like_count AS likeCount FROM tblQuestionBoard qb LEFT JOIN tblUser u ON qb.user_id = u.user_id) UNION ALL (SELECT rb.review_post_id AS seq_id, 'tblReviewBoard' AS boardType, rb.review_board_title AS title, u.nickname AS nickname, rb.review_board_regdate AS regdate, rb.review_board_count AS viewCount, (SELECT COUNT(*) FROM tblReviewComment WHERE review_post_id = rb.review_post_id) AS commentCount, (SELECT COUNT(*) FROM tblReviewLike WHERE review_post_id = rb.review_post_id) AS likeCount FROM tblReviewBoard rb LEFT JOIN tblUser u ON rb.user_id = u.user_id) UNION ALL (SELECT fb.find_board_id AS seq_id, 'tblFindBoard' AS boardType, fb.find_board_title AS title, u.nickname AS nickname, fb.find_board_regdate AS regdate, fb.find_board_view_count AS viewCount, (SELECT COUNT(*) FROM tblFindComment WHERE find_board_id = fb.find_board_id) AS commentCount, (SELECT COUNT(*) FROM tblFindLikes WHERE find_board_id = fb.find_board_id) AS likeCount FROM tblFindBoard fb LEFT JOIN tblUser u ON fb.user_id = u.user_id) UNION ALL (SELECT hd.hotdeal_id AS seq_id, 'tblHotDealPost' AS boardType, hd.hotdeal_title AS title, u.nickname AS nickname, hd.hotdeal_regdate AS regdate, hd.hotdeal_view_count AS viewCount, (SELECT COUNT(*) FROM tblHotDealComment WHERE hotdeal_id = hd.hotdeal_id) AS commentCount, (SELECT COUNT(*) FROM tblHotDealLikes WHERE hotdeal_id = hd.hotdeal_id) AS likeCount
FROM tblHotDealPost hd LEFT JOIN tblUser u ON hd.user_id = u.user_id)
) combined_boards
) paged_boards WHERE RNUM BETWEEN #{startRow} AND #{endRow}
